/// Returns the narrower domains one block's states admit, in key order.
pub fn block_domains(block: &str) -> &'static [(BlockProperty, super::PropertyDomain)] {
    match block {
        "minecraft:acacia_trapdoor"
        | "minecraft:bamboo_trapdoor"
        | "minecraft:bed"
        | "minecraft:bee_nest"
        | "minecraft:beehive"
        | "minecraft:bell"
        | "minecraft:birch_trapdoor"
        | "minecraft:cherry_trapdoor"
        | "minecraft:chiseled_bookshelf"
        | "minecraft:compound_creator"
        | "minecraft:copper_trapdoor"
        | "minecraft:crimson_trapdoor"
        | "minecraft:dark_oak_trapdoor"
        | "minecraft:decorated_pot"
        | "minecraft:element_constructor"
        | "minecraft:exposed_copper_trapdoor"
        | "minecraft:grindstone"
        | "minecraft:iron_trapdoor"
        | "minecraft:jungle_trapdoor"
        | "minecraft:lab_table"
        | "minecraft:loom"
        | "minecraft:mangrove_trapdoor"
        | "minecraft:material_reducer"
        | "minecraft:oxidized_copper_trapdoor"
        | "minecraft:pale_oak_trapdoor"
        | "minecraft:poplar_trapdoor"
        | "minecraft:spruce_trapdoor"
        | "minecraft:trapdoor"
        | "minecraft:tripwire_hook"
        | "minecraft:warped_trapdoor"
        | "minecraft:waxed_copper_trapdoor"
        | "minecraft:waxed_exposed_copper_trapdoor"
        | "minecraft:waxed_oxidized_copper_trapdoor"
        | "minecraft:waxed_weathered_copper_trapdoor"
        | "minecraft:weathered_copper_trapdoor" => &[(
            BlockProperty::Direction,
            super::PropertyDomain::Int(&[0, 1, 2, 3]),
        )],
        "minecraft:activator_rail" | "minecraft:detector_rail" | "minecraft:golden_rail" => &[(
            BlockProperty::RailDirection,
            super::PropertyDomain::Int(&[0, 1, 2, 3, 4, 5]),
        )],
        "minecraft:chorus_flower" => &[(
            BlockProperty::Age,
            super::PropertyDomain::Int(&[0, 1, 2, 3, 4, 5]),
        )],
        "minecraft:cocoa" => &[
            (BlockProperty::Age, super::PropertyDomain::Int(&[0, 1, 2])),
            (
                BlockProperty::Direction,
                super::PropertyDomain::Int(&[0, 1, 2, 3]),
            ),
        ],
        "minecraft:frosted_ice" | "minecraft:nether_wart" => &[(
            BlockProperty::Age,
            super::PropertyDomain::Int(&[0, 1, 2, 3]),
        )],
        "minecraft:shelf_mushroom" => {
            &[(BlockProperty::Growth, super::PropertyDomain::Int(&[0, 1]))]
        }
        _ => &[],
    }
}
